1	// Collie's page API (ADR 0085, decided in #472).
2	// Playwright's page API (ADR 0019) under its names where the meaning is the same, with the guard's
3	// guarantees:
4	// - Pages, Sessions and frames are values. The Session is Playwright's context: pages open with
5	//   `session.newPage()` or arrive as popups, and frames are reached through FrameLocators. There is
6	//   no active page, no frame pointer and no element handle: a Locator is resolved again at each use.
7	// - Every action, and every read of one element, waits through the guard until exactly one element
8	//   matches and is actionable, or its deadline passes; a match still ambiguous then throws
9	//   `TargetNotUniqueError` listing every match.
10	// - The engine runs a page's gestures (actions, keyboard, mouse and touch input, navigations) one at a
11	//   time in arrival order; reads, waits, `evaluate` and answers to routes and dialogs run concurrently.
12	// - A page function is JavaScript run in the page, with one explicit argument; values cross as JSON.
13	// - Routes and dialog handlers answer requests: later ones first, the first to settle wins, one that
14	//   settles nothing falls through, and past the last one a request goes to the network and a dialog
15	//   gets Playwright's default, so a handler that answers nothing never stalls the page.
16	// - A gesture that waits on the program (a locator handler's turn before an attempt, or a route's
17	//   answer to a request it waits on, after its input) gives up its page's turn, only between its own
18	//   inputs, so a handler's own gestures run and no two gestures' inputs interleave. An open dialog
19	//   blocks input, so a dialog handler answers before it acts on the page.
20	// Waits come from ADR 0080 (time.d.ts), events and Subscriptions from ADR 0081 (concurrency.d.ts).
21	
22	import type { AIVerbs, AriaSnapshots } from "./ai.js";
23	import type { RawCall } from "./catalog.js";
24	import type { Listener, Subscription } from "./concurrency.js";
25	import type { JSONObject, JSONValue } from "./data.js";
26	import type { Closeable, Page, Session } from "./lifecycle.js";
27	import type { PageError, ProgramError, RefusedError, UnavailableError } from "./results.js";
28	import type { HeadersInput, JSONValueWithSecrets, SecretPlaceholder } from "./sessions.js";
29	import type { CallOptions, Count, LoadState, URLMatcher } from "./time.js";
