1	// Models, usage and cost in the SDK API (ADR 0101, decided in #475).
2	// - A program names a model by a Model reference, `"<provider>/<model id>"`: the setting `ai.model`
3	//   for a scope, or the AI verbs' per-call `model` (ADR 0091), which is that setting at the run layer.
4	//   `ai.model` has no default: no model is called unless one is configured (ADR 0043).
5	// - Model providers are built in (`openai`, `anthropic`, `google`, `vercel`, `openrouter`, and the
6	//   local `ollama`, `llamacpp`, `lmstudio`, `vllm`), declared under `ai.providers.<name>`, a Model
7	//   provider Plugin the operator allowed (ADR 0033), named by its manifest, or an SDK handler
8	//   registered on the connection (ADR 0033's SDK-handler form). Provider names form one namespace.
9	// - Capabilities are declared, never sniffed from a name; prices come from the price table, set only
10	//   in configuration, so no Client can lower the price a person's currency Limit is held to.
11	// - Every AI result carries its `ModelUsage`, priced; `run.usage()` gives the Run's totals, what
12	//   remains of each Limit and ADR 0041's uncapped mark. An error from a call that made model calls
13	//   carries its `usage` too.
14	
15	import type { JSONSchema } from "./data.js";
16	import type { LimitSource, ModelError, ProgramError, RefusedError, UnavailableError } from "./results.js";
17	import type { SecretReference } from "./sessions.js";
18	import type { CallOptions, Money } from "./time.js";
19	
20	// Naming a model.
21	
22	/**
23	 * A Model reference: a Model provider's name, a slash, and that provider's own model ID verbatim, so a
24	 * gateway's ID keeps its slash: `"anthropic/claude-sonnet-4-5"`, `"vercel/anthropic/claude-sonnet-4.5"`,
25	 * `"ollama/qwen3:8b"`. The provider must be built in, declared, an allowed Model provider Plugin or
26	 * the program's own where the scope opens (`setting_invalid`, naming the closest); the model ID is
27	 * the provider's to accept (`model_not_found`).
28	 */
29	export type ModelReference = `${string}/${string}`;
30	
31	/** The built-in Model providers. A local one sits at its server's default loopback address. */
32	export type BuiltinModelProvider =
33	  | "openai"
34	  | "anthropic"
35	  | "google"
36	  | "vercel"
37	  | "openrouter"
38	  | "ollama"
39	  | "llamacpp"
40	  | "lmstudio"
41	  | "vllm";
42	
43	/** ADR 0012's three request formats. */
44	export type ModelFormat = "openai" | "anthropic" | "gemini";
45	
46	/** How the engine gets JSON that fits a schema: the provider's schema mode, a forced tool call, or the schema in the prompt with repair. */
47	export type StructuredOutputStrategy = "native" | "tool" | "prompt";
48	
49	/**
50	 * What a model can take and produce, declared rather than inferred from its name. The shipped list
51	 * covers the tested models (ADR 0065); a model it does not know is text only, gets structured output
52	 * from the top of the ladder (`prompt` for the program's own provider), and has no price. Its price
53	 * is the price table's, overridden only in configuration under
54	 * `ai.providers.<name>.models.<id>.price`, so it is no key here: a price set in code fails with
55	 * `setting_locked`. A model ID holding a dot or a slash is one quoted segment of a key:
56	 * `ai.providers.lab.models."gpt-5.1".image_input`.
57	 */
58	export interface ModelDeclaration {
59	  readonly contextWindow?: number;
60	  readonly maxOutputTokens?: number;
61	  readonly imageInput?: boolean;
62	  readonly toolCalls?: boolean;
63	  /** The structured output strategies the model accepts, best first. */
64	  readonly strategies?: readonly StructuredOutputStrategy[];
65	}
66	
67	/**
68	 * `ai.providers.<name>`: a Model provider the program declares, or a built-in it changes (a proxy in
69	 * front of OpenAI), at the connection, a Run or a Session. `apiKey` and `headers` go only to
70	 * `baseURL`. A built-in's default key (its conventional variable, such as `env:OPENAI_API_KEY`) goes
71	 * only to its own address, so a built-in pointed elsewhere sends none. `apiKey`, `headers` and
72	 * `baseURL` are set by the program's own code, configuration or an Operator policy: a Recipe and a
73	 * Client acting for a model, an Integration included, never set them (`setting_locked`). For the
74	 * program's own provider, only `models` applies.
75	 */
76	export interface ModelProviderSettings {
77	  readonly format?: ModelFormat;
78	  readonly baseURL?: string;
79	  readonly apiKey?: SecretReference | null;
80	  /** Header values are Secret references, as ADR 0056's `cdp_url` headers. */
81	  readonly headers?: Readonly<Record<string, SecretReference>>;
82	  /** Capabilities by the provider's own model ID. */
83	  readonly models?: Readonly<Record<string, ModelDeclaration>>;
84	}
85	
86	/** `ai.*`. */
87	export interface AISettings {
88	  /** `ai.model`: the model every AI call of the scope uses unless the call names its own. No default. */
89	  readonly model?: ModelReference | null;
90	  readonly providers?: Readonly<Record<string, ModelProviderSettings>>;
91	  /**
92	   * `ai.structured_output`: `auto` (the default) starts at the best strategy the model declares, or
93	   * `native` for one it does not know, and steps down when the provider rejects a strategy or a schema
94	   * feature; an answer that fails validation is retried, never stepped down. Every answer is validated
95	   * against the program's own schema and validators (ADR 0082).
96	   */
97	  readonly structuredOutput?: "auto" | StructuredOutputStrategy;
98	  /**
99	   * `ai.allowance.*`: the Run's Model allowance (ADR 0107), set where a Run opens or above, never on a
100	   * Label, a Session or a page (`setting_not_applicable`). Not a Limit: once reached, every later model
101	   * call of the Run raises `ModelAllowanceReachedError` while the Run goes on.
102	   */
103	  readonly allowance?: ModelAllowanceSettings;
104	}
105	
106	/**
107	 * `ai.allowance.*`: the most model Usage one Run may spend (ADR 0107), none by default, `null` for none.
108	 * Each call reserves its worst case against it, so it is never passed; the first call that does not fit
109	 * is refused, and so is every later model call of the Run, a smaller one included. When several are
110	 * set, the first reached holds. Any layer may set it, a Recipe and a Client acting for a model
111	 * included; the Limits still stop the Run, and only they clear the uncapped mark.
112	 */
113	export interface ModelAllowanceSettings {
114	  /** `ai.allowance.price`: priced through the price table; an unpriced model is refused with `model_price_unknown`. */
115	  readonly price?: Money | null;
116	  /** `ai.allowance.tokens`: input plus output, as `ModelUsage.tokens`. */
117	  readonly tokens?: number | null;
118	  /** `ai.allowance.calls`: as `ModelUsage.calls`. */
119	  readonly calls?: number | null;
120	}
121	
122	// The SDK handler: ADR 0033's SDK-handler form of the Model provider kind.
123	
124	export type ModelMessage =
125	  | { readonly role: "system"; readonly content: string }
126	  | { readonly role: "user"; readonly content: readonly ModelContentPart[] }
127	  | { readonly role: "assistant"; readonly content: readonly ModelContentPart[]; readonly toolCalls?: readonly ModelToolCall[] }
128	  | { readonly role: "tool"; readonly toolCallId: string; readonly content: string };
129	
130	export type ModelContentPart =
131	  | { readonly type: "text"; readonly text: string }
132	  | { readonly type: "image"; readonly mediaType: string; readonly data: Uint8Array };
133	
134	export interface ModelTool {
135	  readonly name: string;
136	  readonly description: string;
137	  readonly inputSchema: JSONSchema;
138	}
139	
140	/** Whether the answer must call a tool: `tool` is the forced tool call of the `tool` strategy. */
141	export type ModelToolChoice = { readonly type: "auto" } | { readonly type: "none" } | { readonly type: "tool"; readonly name: string };
142	
143	export interface ModelToolCall {
144	  readonly id: string;
145	  readonly name: string;
146	  /** The arguments as JSON text, as the model wrote them: the engine parses and validates them. */
147	  readonly arguments: string;
148	}
149	
150	/** What the engine asks a handler: Goodfetch's own types, exported, so no provider SDK is needed (G7). */
151	export interface ModelRequest {
152	  /** The model ID after the provider's name in the Model reference. */
153	  readonly modelId: string;
154	  /** The Run asking. */
155	  readonly runId: string;
156	  readonly messages: readonly ModelMessage[];
157	  readonly tools: readonly ModelTool[];
158	  readonly toolChoice: ModelToolChoice;
159	  /** Set when the strategy is `native`: the answer must be JSON fitting it. */
160	  readonly responseSchema: JSONSchema | null;
161	  readonly maxOutputTokens: number;
162	  /** Aborted when `timeout.model` passes or the call is cancelled (`$/cancel`). */
163	  readonly signal: AbortSignal;
164	}
165	
166	/** The token counts a handler reports: input and output are required, so a Limit counts every call. */
167	export interface ReportedTokens {
168	  readonly inputTokens: number;
169	  readonly outputTokens: number;
170	  readonly cacheReadTokens?: number;
171	  readonly cacheWriteTokens?: number;
172	  readonly reasoningTokens?: number;
173	}
174	
175	/** The program's answer; a refusal is `finishReason: "refusal"`, which the engine raises as `model_declined`. */
176	export interface ModelResponse {
177	  readonly text: string;
178	  readonly toolCalls?: readonly ModelToolCall[];
179	  readonly finishReason: "stop" | "length" | "tool_calls" | "refusal" | (string & {});
180	  readonly usage: ReportedTokens;
181	}
182	
183	/**
184	 * Answers model calls for the provider name it is registered under, where the program's own code runs
185	 * (ADR 0081). The engine journals, counts and caps each call (ADR 0012); it gets the `prompt` strategy
186	 * unless its models declare others, and only configuration prices it. A `GoodfetchError` it throws
187	 * keeps its code (a `ModelUnavailableError` is retried as a provider's would be); any other exception
188	 * is `model_handler_failed`.
189	 */
190	export type ModelProviderHandler = (request: ModelRequest) => Promise<ModelResponse>;
191	
192	// Usage and its price.
193	
194	/**
195	 * Token counts in OpenTelemetry's and the AI SDK's convention, whatever the provider's: input counts
196	 * every input token, cached ones included (Anthropic's three counts are summed), and output counts
197	 * reasoning tokens.
198	 */
199	export interface TokenCounts {
200	  /** Model calls sent, retries and Repairs included; a step replayed from the Plan sends none. */
201	  readonly calls: number;
202	  /** Input plus output: what `limits.modelTokens` counts. */
203	  readonly tokens: number;
204	  readonly inputTokens: number;
205	  /** Part of `inputTokens`. */
206	  readonly cacheReadTokens: number;
207	  /** Part of `inputTokens`. */
208	  readonly cacheWriteTokens: number;
209	  readonly outputTokens: number;
210	  /** Part of `outputTokens`. */
211	  readonly reasoningTokens: number;
212	  /**
213	   * Their price from the price table: a list-price estimate, never a bill, in the table's currency
214	   * (USD as shipped), other currencies converted only through the table's fixed rates. `null` when
215	   * part of it has no price, or needs a rate the table lacks: never a partial sum.
216	   */
217	  readonly price: Money | null;
218	}
219	
220	export interface ModelUsageOf extends TokenCounts {
221	  readonly model: ModelReference;
